    const c_cam_2 = ui.must(await ui.addClaimTwice(pg_vic, p_cam, {"amount": "25.00", "date": "2026-03-20"}));
    expect(await ui.claimCount(pg_vic, p_cam)).toBe(3);
    await ui.refresh(pg_uma);
    await ui.showRetired(pg_uma, true);
